import {LANDINGS,landingFor,campaignCells} from './campaign.js';
import {cleanBuild,DEFAULT_BUILD,EQUIPMENT,ABILITIES,mechStats,buildKey,validBuild} from './core.js?v=41';
import {itemIcon} from './workshop-icons.js?v=41';

const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=id=>EQUIPMENT[id].name.split(' / ').at(-1);
export const CAMPAIGN_MECHS=[
  {label:'Vanguard',role:'Balanced assault',build:cleanBuild(DEFAULT_BUILD)},
  {label:'Kestrel',role:'Mobile skirmisher',build:cleanBuild({frame:'scout',equipment:['claws','scatter','emp'],color:'#74adca'})},
  {label:'Bastion',role:'Armored support',build:cleanBuild({parts:{torso:'heavy',head:'standard',arms:'standard',legs:'standard',booster:'heavy'},equipment:['guard','carbine','repair'],color:'#b3c9bd'})}
];
function mapMarkup(campaign,inspected,canChoose){
  const points=(x,y)=>Array.from({length:6},(_,i)=>{const a=(60*i-30)*Math.PI/180;return`${(x+37*Math.cos(a)).toFixed(1)},${(y+37*Math.sin(a)).toFixed(1)}`;}).join(' ');
  return `<svg class="campaign-map" viewBox="0 0 850 500" aria-labelledby="campaignMapTitle campaignMapDesc"><title id="campaignMapTitle">Kepler-9 campaign territories</title><desc id="campaignMapDesc">Green allied cells, red hostile cells, amber contested cells and gray uncharted cells. Three marked landing zones deploy into Cinderfall. Other territories are future fronts.</desc>
    <defs><pattern id="mapGrid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#9db5a2" stroke-opacity=".05"/></pattern></defs><rect width="850" height="500" fill="url(#mapGrid)"/>
    <path class="map-river" d="M298 0 322 70 278 143 336 198 311 275 372 331 353 398 403 500"/>
    ${campaignCells(campaign).map(cell=>{const selected=inspected===cell.id,landing=cell.landing,active=landing?.id===campaign.landing;return `<g class="territory ${cell.control}${selected?' inspected':''}${active?' active':''}" role="button" tabindex="0" data-cell="${cell.id}" aria-label="${landing?`Cinderfall: ${landing.name}, ${active?'selected landing zone':canChoose?'available landing zone':'host selects landing'}`:`${cell.control} territory ${String.fromCharCode(65+cell.col)}${cell.row+1}, future front`}" aria-pressed="${selected}"><polygon points="${points(cell.x,cell.y)}"/><text class="cell-coordinate" x="${cell.x}" y="${cell.y+17}">${String.fromCharCode(65+cell.col)}${cell.row+1}</text>${landing?`<circle cx="${cell.x}" cy="${cell.y-5}" r="13"/><text class="landing-code" x="${cell.x}" y="${cell.y}">${landing.code}</text>`:cell.control==='hostile'&&cell.col%3===0?`<path class="hostile-mark" d="M${cell.x-5} ${cell.y-8}l10 10m0-10-10 10"/>`:''}</g>`;}).join('')}
    <g class="map-labels"><text x="112" y="230">ALLIED FOOTHOLD</text><text x="530" y="225">OCCUPIED BADLANDS</text><text x="334" y="334" class="map-focus-label">CINDERFALL</text><text x="334" y="352">FREIGHT CANYON / ACTIVE FRONT</text><text x="130" y="465">K-9 / SURFACE COMMAND</text><text x="703" y="465">N ↑</text></g>
  </svg>`;
}
export function createCampaignView(root,actions){
  let inspected='3-3',latest;
  root.addEventListener('click',event=>{
    const target=event.target.closest('[data-action],[data-cell]');if(!target)return;
    if(target.dataset.cell){inspected=target.dataset.cell;const landing=LANDINGS.find(p=>p.cell===inspected);if(landing&&latest.canChoose)actions.landing(landing.id);else render(latest);return;}
    const action=target.dataset.action;
    if(action==='focus'){inspected=landingFor(latest.campaign).cell;render(latest);return;}
    actions[action]?.();
  });
  root.addEventListener('keydown',event=>{if(event.target.matches('[data-cell]')&&['Enter',' '].includes(event.key)){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
  root.addEventListener('change',event=>{if(event.target.id==='campaignMech')actions.mech(event.target.value);if(event.target.id==='campaignSpecial')actions.special(event.target.value);if(event.target.id==='campaignLanding')actions.landing(event.target.value);});
  function render(state){
    if(state.campaign?.id!==latest?.campaign?.id||state.campaign?.landing!==latest?.campaign?.landing)inspected=landingFor(state.campaign).cell;
    latest=state;const {campaign,build,saved,members,localId,room,isHost,connecting,canChoose}=state;
    if(!campaign){root.innerHTML='';return;}
    const focused=root.contains(document.activeElement)?document.activeElement:null,focusId=focused?.id,focusCell=focused?.dataset.cell;
    const landing=landingFor(campaign),cell=campaignCells(campaign).find(c=>c.id===inspected),available=!!cell?.landing,valid=validBuild(build),stats=mechStats(build),self=members.find(p=>p.id===localId),allReady=members.every(p=>p.ready&&validBuild(p.build));
    const presets=CAMPAIGN_MECHS.map((p,i)=>({value:`preset-${i}`,label:`${p.label} · ${p.role}`,build:p.build})),savedOptions=saved.map((b,i)=>({value:`saved-${i}`,label:`Saved · ${b.name}`,build:b})),options=[...presets,...savedOptions];
    const match=options.find(p=>buildKey({...p.build,equipment:[...p.build.equipment.slice(0,2),build.equipment[2]]})===buildKey(build));
    const result={victory:'Cinderfall secured. Allied control established. Redeploy to defend the canyon.',defeat:'Sortie lost. Regroup, refit, and reclaim the canyon.',withdrawal:'Squad withdrawn. The front awaits your next deployment.'}[campaign.lastResult];
    root.innerHTML=`<header class="campaign-heading"><div><p class="overline">CAMPAIGN / KEPLER-9</p><h1>The Cinder Front<span class="campaign-live">● ${room?'SQUAD CAMPAIGN':'SOLO CAMPAIGN'}</span></h1></div><div class="campaign-totals"><span><b>${campaign.sorties}</b> SORTIES</span><span><b>${campaign.victories?'03':'00'}</b> / 03 CELLS SECURED</span><button class="text-button" data-action="home">Main menu ↗</button></div></header>
    ${result?`<p class="campaign-result" role="status">${escape(result)}</p>`:''}
    <div class="campaign-layout"><section class="campaign-theater" aria-label="Campaign overworld"><div class="theater-heading"><span>01 / SELECT A BATTLEFIELD</span><span>${room?(isHost?'YOU COMMAND THE SQUAD':'HOST COMMANDS THE SQUAD'):'COMMAND UPLINK / ONLINE'}</span></div>${mapMarkup(campaign,inspected,canChoose)}<div class="map-legend"><span class="allied">● Allied</span><span class="contested">● Contested</span><span class="hostile">● Hostile</span><span class="unknown">● Uncharted</span><span>◎ Deployment zone</span></div><p class="map-caption">${canChoose?'Select a marked cell to choose your insertion.':'Inspect the front. Your host selects the shared insertion.'} All three landing zones enter the Cinderfall battlefield.</p></section>
    <aside class="campaign-briefing" aria-label="Selected battlefield"><p class="overline">${available?'ACTIVE BATTLEFIELD / 01':'RECON / FUTURE FRONT'}</p><h2>${available?'Cinderfall':cell?.control==='unknown'?'Uncharted territory':'Outer territories'}</h2><p class="battlefield-tags">${available?'FREIGHT CANYON · ~15 MIN · 1–4 PILOTS':'NO PLAYABLE BATTLEFIELD'}</p><div class="canyon-thumbnail" aria-hidden="true"><i></i><i></i><i></i><span>${available?'K-9 / CINDERFALL':'SIGNAL UNAVAILABLE'}</span></div><p class="battlefield-description">${available?'Break the orbital batteries. Fuel the crawler. Destroy the reactor warden and extract together.':'The wider campaign is taking shape. This territory has no mission yet. Cinderfall is the only playable battlefield in this campaign outline.'}</p>${available?`<label class="campaign-field" for="campaignLanding">INSERTION POINT<select id="campaignLanding" ${!canChoose?'disabled':''}>${LANDINGS.map(p=>`<option value="${p.id}" ${p.id===campaign.landing?'selected':''}>${p.code} / ${p.name}</option>`).join('')}</select></label><p class="landing-detail">${escape(landing.detail)}</p><div class="briefing-objectives"><span>01 / LAND & BREACH</span><span>02 / BATTERIES & CRAWLER</span><span>03 / REACTOR & EXTRACTION</span></div>`:`<button class="button secondary" data-action="focus">Locate Cinderfall ↗</button>`}<p class="campaign-scope">One battlefield. Three insertion points.<br>Wider fronts will open in future updates.</p></aside></div>
    <section class="campaign-loadout" aria-label="Deployment loadout"><div class="loadout-heading"><span>02 / PREPARE YOUR MECH</span><button class="text-button" data-action="workshop">Customize in workshop ↗</button></div><div class="deployment-fitting"><label class="campaign-field" for="campaignMech">MECH<select id="campaignMech"><option value="current" ${!match?'selected':''}>Current / ${escape(build.name)}</option>${options.map(p=>`<option value="${p.value}" ${match?.value===p.value?'selected':''}>${escape(p.label)}</option>`).join('')}</select></label><div class="fitted-hands"><span>${itemIcon('equip0',build.equipment[0],EQUIPMENT[build.equipment[0]])}<small>LEFT HAND</small><strong>${short(build.equipment[0])}</strong></span><span>${itemIcon('equip1',build.equipment[1],EQUIPMENT[build.equipment[1]])}<small>RIGHT HAND</small><strong>${short(build.equipment[1])}</strong></span></div><label class="campaign-field" for="campaignSpecial">SPECIAL WEAPON / E<select id="campaignSpecial">${Object.entries(ABILITIES).map(([id,item])=>`<option value="${id}" ${build.equipment[2]===id?'selected':''}>${item.name} · ${item.weight}t</option>`).join('')}</select></label><div class="deployment-stats ${valid?'':'overloaded'}"><strong>${stats.weight} / ${stats.capacity}t</strong><span>${valid?`${stats.hp} armor · ${stats.weightClass.toLowerCase()} frame`:'OVERLOADED · Refit to deploy'}</span></div></div><p class="special-detail">${escape(ABILITIES[build.equipment[2]].desc)}${room?' · Changing your loadout clears your ready status.':''}</p></section>
    <section class="campaign-squad" aria-label="Campaign squad"><div class="campaign-squad-heading"><span>03 / ASSEMBLE & DEPLOY <small>${members.length} / 4 PILOTS</small></span><div>${room?`<span class="room-code">ROOM ${escape(room)} · ${isHost?'HOST':'GUEST'}</span><button class="text-button" data-action="invite">Copy invite</button><button class="text-button" data-action="leave">Leave squad</button>`:`<button class="text-button" data-action="host" ${connecting?'disabled':''}>Host friends ＋</button><button class="text-button" data-action="join" ${connecting?'disabled':''}>Join squad ↗</button>`}</div></div><div class="campaign-launch-row"><div class="campaign-pilots">${Array.from({length:4},(_,i)=>{const p=members[i];return p?`<div class="campaign-pilot${p.ready?' ready':''}"><span class="pilot-index">0${i+1}</span><div><strong>${escape(p.name)}${p.id===localId?' / YOU':''}</strong><small>${escape(p.build.name)}</small><small>${escape(short(p.build.equipment[2]))}</small></div><em>${room?(p.ready?'READY':'FITTING'):'SOLO'}</em></div>`:`<button class="campaign-pilot open" data-action="${room?'invite':'host'}" ${connecting?'disabled':''}><span class="pilot-index">＋</span><span>OPEN SLOT<small>Invite a pilot</small></span></button>`;}).join('')}</div><div class="campaign-deploy-actions">${room?`<button class="button secondary" data-action="ready" ${connecting||(!valid&&!self?.ready)?'disabled':''}>${self?.ready?'Unready':'Mark ready ✓'}</button>`:''}<button class="button primary" data-action="deploy" ${connecting||!available||!valid||(room&&(!isHost||!allReady))?'disabled':''}>${!available?'FRONT UNAVAILABLE':room?(isHost?'DEPLOY SQUAD ↗':'AWAITING HOST'):'DEPLOY SOLO ↗'}</button></div></div><p class="campaign-network-status" role="status">${connecting?'Connecting to the squad…':room?`${members.filter(p=>p.ready).length}/${members.length} pilots ready. ${isHost?'Everyone must mark ready before you deploy.':'Your host selects the landing zone and launches the squad.'}`:'Solo is ready immediately. Host a room to deploy with up to three friends.'}</p></section>`;
    if(focusId)root.querySelector(`#${focusId}`)?.focus({preventScroll:true});else if(focusCell)root.querySelector(`[data-cell="${focusCell}"]`)?.focus({preventScroll:true});
  }
  return {render,focusLanding(campaign){inspected=landingFor(campaign||latest?.campaign).cell;}};
}
